    const lo = K.quantile(sorted, 0.5), hi = sorted[sorted.length - 1];
    const c = K.chart($('#an-svg'), { width: 620, height: Math.round(576 * (lim[3] - lim[2]) / (lim[1] - lim[0])) + 44, x: [lim[0], lim[1]], y: [lim[2], lim[3]], margin: { left: 34, right: 10, top: 10, bottom: 34 } });
    grid.forEach(([a, b, sx, sy, s]) => { const t = K.clamp((s - lo) / (hi - lo + 1e-12), 0, 1); if (t > 0.02) { const r = c.rect(a, b, a + sx, b + sy, 's5'); r.style.fillOpacity = 0.55 * t; r.style.stroke = 'none'; } });
    c.axes({ xTicks: 6, yTicks: 5, grid: false });
    X.forEach((p, i) => {
      const d = c.dot(p[0], p[1], isPl[i] ? 5 : 3.6, (alert[i] ? 's5' : 's1') + ' dot');
      if (alert[i]) { d.style.stroke = 'var(--lab-text)'; d.style.strokeWidth = 1.5; }
      if (isPl[i]) { const ring = c.dot(p[0], p[1], 9, 's2 line'); ring.style.strokeWidth = 2; }
    });
    const s = 9, Xq = c.X(q[0]), Yq = c.Y(q[1]);
    K.el('path', { d: `M${Xq},${Yq - s}L${Xq + s},${Yq}L${Xq},${Yq + s}L${Xq - s},${Yq}Z`, class: 's4 dot drag' }, c.g).style.strokeWidth = 2;
    const qs = score(q), pct = 100 * sorted.filter(v => v < qs).length / sorted.length;
    const hits = planted.filter(i => alert[i]).length, prec = hits / alert.filter(Boolean).length;
    $('#an-hit').textContent = `${hits} de ${planted.length}`;
    $('#an-prec').textContent = K.fmt(100 * prec, 0) + ' %';
    $('#an-q').textContent = K.fmt(qs, m === 'iforest' ? 3 : 2);
    $('#an-qp').textContent = K.fmt(pct, 0) + (qs >= thr ? ' (alerta)' : '');
    const name = { maha: 'Mahalanobis', knn: 'k-vecinos', lof: 'LOF', iforest: 'Isolation Forest' }[m];
    const missed = planted.filter(i => !alert[i]).length;
    let msg = `${name}: ${nAlert} alertas (${cont} %), ${hits} de las ${planted.length} anomalías plantadas detectadas y ${nAlert - hits} falsas alarmas. `;
    if (m === 'maha') msg += covSeg.get() === 'clasica' ? 'La elipse se ajusta a todos los datos, incluidos los dos grupos y las anomalías: la covarianza clásica queda inflada y las regiones raras entre grupos pasan desapercibidas.' : 'Con la covarianza robusta, la elipse se ajusta al núcleo más compacto de los datos (el grupo denso): todo lo que se aparte de su correlación destaca, incluido, por cierto, el grupo disperso entero.';
    else if (m === 'knn') msg += 'La distancia al k-ésimo vecino usa una escala global: la periferia del grupo disperso parece tan rara como los puntos aislados.';
    else if (m === 'lof') msg += 'LOF compara cada punto con la densidad de sus vecinos: las anomalías pegadas al grupo denso destacan y el grupo disperso se considera normal.';
    else msg += 'Isolation Forest corta en paralelo a los ejes: lo que se aísla con pocos cortes recibe puntuación alta. Es rápido y global.';
    const note = $('#an-note'); note.className = 'plab-note ' + (missed === 0 ? 'good' : missed > 2 ? 'warn' : ''); note.textContent = msg;
  }
  const svg = $('#an-svg');
  svg.addEventListener('pointerdown', e => { if (e.target.closest('path.drag')) { drag = true; svg.setPointerCapture(e.pointerId); } });
  svg.addEventListener('pointermove', e => { if (!drag) return; const [x, y] = svg.__chart.pointer(e); q = [K.clamp(x, lim[0], lim[1]), K.clamp(y, lim[2], lim[3])]; render(); });
  svg.addEventListener('pointerup', () => { drag = false; });
  $('#an-k').addEventListener('change', recompute);
  $('#an-k').addEventListener('input', () => { $('#an-k-v').textContent = $('#an-k').value; });
  $('#an-c').addEventListener('input', render);
  recompute();
})();
</script>
