## Implementación en Python

### El sensor: puntuación $z$, Mahalanobis y covarianza robusta

::: {#an-sensor .cell execution_count=1}
``` {.python .cell-code}
import numpy as np
import pandas as pd
from scipy.stats import chi2
from sklearn.covariance import EmpiricalCovariance, MinCovDet

sensor = pd.DataFrame({"temp": [60, 62, 64, 66, 68, 70, 72, 74, 76, 69],
                       "pres": [120, 125, 127, 133, 135, 141, 143, 149, 151, 126]}, index=range(1, 11))
z = (sensor - sensor.mean()) / sensor.std()
print("puntuaciones z de la lectura 10:", z.loc[10].round(2).to_dict())

umbral = np.sqrt(chi2.ppf(0.975, df=2))
clasica = EmpiricalCovariance().fit(sensor)
referencia = EmpiricalCovariance().fit(sensor.loc[1:9])
robusta = MinCovDet(random_state=0).fit(sensor)
tabla = pd.DataFrame({
    "clásica (10 lecturas)": np.sqrt(clasica.mahalanobis(sensor)),
    "solo referencia (9)": np.sqrt(referencia.mahalanobis(sensor)),
    "robusta (MCD)": np.sqrt(robusta.mahalanobis(sensor)),
}, index=sensor.index).round(2)
print(f"\numbral χ² (97.5 %): d_M > {umbral:.2f}")
print(tabla.T)
```

