``` {.python .cell-code}
from sklearn.metrics import roc_auc_score, average_precision_score

def precision_en_n(y, s, n):
    return y[np.argsort(-s)[:n]].mean()

filas = {nombre: {"ROC AUC": roc_auc_score(y, s), "AP (área PR)": average_precision_score(y, s),
                  "precisión en las 15 primeras": precision_en_n(y, s, 15)} for nombre, s in puntuaciones.items()}
print(pd.DataFrame(filas).T.round(3))
print(f"\nproporción de anomalías: {y.mean():.3f} (AP de un detector al azar)")
